#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_is_finite.h"

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
constexpr int64_t COMPARE_ALIGN_BYTES = 256;
constexpr int64_t UB_ALIGN_BYTES = 32;

at::Tensor is_finite(const at::Tensor &self)
{
    // ---- 输入校验 ----
    TORCH_CHECK(self.scalar_type() == at::kHalf || self.scalar_type() == at::kFloat,
                "is_finite: only float16 and float32 are supported, got ", self.scalar_type());

    at::Tensor output = at::empty_like(self);

    int64_t totalLength = self.numel();
    if (totalLength == 0) {
        return output;
    }

    int64_t dtypeSize = self.element_size();

    // ---- 获取硬件参数 ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- Block 级 tiling (核间切分, Cache Line 512B 对齐) ----
    int64_t cacheLineElements = CACHE_LINE_BYTE_LENGTH / dtypeSize;
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = ((totalLengthCore + cacheLineElements - 1)
                                     / cacheLineElements) * cacheLineElements;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // ---- UB 级 tiling (核内切分) ----
    // UB 分配表:
    //   fp32: inQueueX[2]*4B + outQueueY[2]*4B + calcBuf*4B + maskBuf*(1/8)B ≈ 20B/elem
    //   fp16: inQueueX[2]*2B + outQueueY[2]*2B + calcBuf[2]*4B + maskBuf*(1/8)B ≈ 16B/elem
    int64_t bufferCoefficient;
    if (dtypeSize == 2) {
        bufferCoefficient = 16;  // fp16
    } else {
        bufferCoefficient = 20;  // fp32
    }
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;

    // 32B DataCopyPad 对齐 & 256B Compare 对齐
    int64_t ubAlignElements = UB_ALIGN_BYTES / dtypeSize;
    int64_t compareAlignElements = COMPARE_ALIGN_BYTES / static_cast<int64_t>(sizeof(float));
    int64_t totalAlignElements = (ubAlignElements > compareAlignElements)
                                  ? ubAlignElements : compareAlignElements;
    int64_t tileLength = (maxTileElements / totalAlignElements) * totalAlignElements;
    if (tileLength == 0) { tileLength = totalAlignElements; }

    EXEC_KERNEL_CMD(is_finite, blockDim,
                    self, output,
                    formerNum, formerLength, tailLength, tileLength, dtypeSize);

    return output;
}

}  // namespace ascend_kernel
