#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;
// Compare API 要求数据区为 256 字节整数倍。Compare 操作始终在 float32 上进行，
// 因此对齐元素数 = 256 / sizeof(float) = 64。
constexpr int64_t COMPARE_ALIGN_ELEMENTS = 64;

// ---- GM↔UB 搬运内联辅助函数 ----

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// ---- Kernel 主类 ----

template <typename T>
class KernelIsFinite {
public:
    __aicore__ inline KernelIsFinite() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength,
                                int64_t dtypeSize)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
        }

        this->tileLength = tileLength;
        this->dtypeSize = dtypeSize;

        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));
        // fp32 临时计算缓冲: Abs结果 + FLT_MAX向量复用
        // fp16 额外需要 fp32 Cast 缓冲
        if constexpr (sizeof(T) == sizeof(float)) {
            pipe.InitBuffer(calcBuf, tileLength * sizeof(float));
        } else {
            pipe.InitBuffer(calcBuf, tileLength * sizeof(float) * 2);
        }
        // uint8_t mask 缓冲: Compare 输出 bitmask, ceil(tileLength/8) 字节
        int64_t maskBytes = (tileLength + 7) / 8;
        maskBytes = ((maskBytes + 31) / 32) * 32;  // 32B 对齐
        pipe.InitBuffer(maskBuf, maskBytes);
    }

    __aicore__ inline void Process()
    {
        if (this->blockLength == 0) { return; }

        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
        // 尾块对齐到 64 元素 (256B, Compare 要求)
        int64_t alignedTailLen = ((tailTileLength + COMPARE_ALIGN_ELEMENTS - 1)
                                   / COMPARE_ALIGN_ELEMENTS) * COMPARE_ALIGN_ELEMENTS;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            CopyIn(i, this->tileLength, this->tileLength);
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength, this->tileLength);
        }
        if (tileNum > 0) {
            CopyIn(tileNum - 1, alignedTailLen, tailTileLength);
            Compute(tileNum - 1, alignedTailLen);
            CopyOut(tileNum - 1, alignedTailLen, tailTileLength);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curLen, int64_t validLen)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
        // validLen 为有效数据长度, curLen 为对齐后长度 (≥ validLen)
        // DataCopyPad 搬入 validLen 个元素, 不足部分 pad
        LoadGmToUb(xLocal, xGm[progress * this->tileLength],
                   static_cast<uint32_t>(validLen));
        if (curLen > validLen) {
            // 手动清零 padding 区域以避免 Compare 误判
            int64_t padCount = curLen - validLen;
            AscendC::LocalTensor<T> padRegion = xLocal[validLen];
            AscendC::Duplicate(padRegion, static_cast<T>(0), padCount);
        }
        inQueueX.EnQue(xLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();

        constexpr float FLT_MAX_F32 = 3.402823466e+38f;

        if constexpr (sizeof(T) == sizeof(float)) {
            // ---- float32 路径: |x| <= FLT_MAX ----
            // 复用 yLocal 作为工作空间: yLocal ← Abs(x)
            AscendC::Abs(yLocal, xLocal, curTileLength);
            // calcBuf ← FLT_MAX
            AscendC::LocalTensor<float> tmpFp32 = calcBuf.Get<float>();
            AscendC::Duplicate(tmpFp32, FLT_MAX_F32, curTileLength);
            // maskBuf ← (|x| <= FLT_MAX)
            AscendC::LocalTensor<uint8_t> mask = maskBuf.Get<uint8_t>();
            AscendC::Compare(mask, yLocal, tmpFp32, AscendC::CMPMODE::LE, curTileLength);
            // 复用 tmpFp32 = 1.0f
            AscendC::Duplicate(tmpFp32, 1.0f, curTileLength);
            // yLocal ← Select(mask, 1.0f, 0.0f)
            AscendC::Select(yLocal, mask, tmpFp32, 0.0f,
                            AscendC::SELMODE::VSEL_TENSOR_SCALAR_MODE, curTileLength);
        } else {
            // ---- float16 路径: Cast → fp32 → 计算 → Cast 回 ----
            AscendC::LocalTensor<float> srcFp32 = calcBuf.Get<float>();
            AscendC::LocalTensor<float> tmpFp32 = srcFp32[curTileLength];

            // Cast fp16→fp32
            AscendC::Cast(srcFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            // Abs in-place: srcFp32 ← |srcFp32|
            AscendC::Abs(srcFp32, srcFp32, curTileLength);
            // tmpFp32 ← FLT_MAX
            AscendC::Duplicate(tmpFp32, FLT_MAX_F32, curTileLength);
            // mask ← (|x| <= FLT_MAX)
            AscendC::LocalTensor<uint8_t> mask = maskBuf.Get<uint8_t>();
            AscendC::Compare(mask, srcFp32, tmpFp32, AscendC::CMPMODE::LE, curTileLength);
            // 复用 srcFp32 = 1.0f
            AscendC::Duplicate(srcFp32, 1.0f, curTileLength);
